def number_existing_tickets(apps, schema_editor):
    """Serial numbers for the tickets issued before, per event, oldest first."""
    Ticket = apps.get_model("tickets", "Ticket")
    counters = {}
    for ticket in Ticket.objects.select_related("order").order_by("created_at", "pk"):
        event_id = ticket.order.event_id
        counters[event_id] = counters.get(event_id, 0) + 1
        Ticket.objects.filter(pk=ticket.pk).update(serial=counters[event_id])


